  const st={tab:'home',data:{},selected:null,detail:null,panel:'brief',seq:0,detailSeq:0,loading:false,error:null,q:'',filter:'active',sort:'recent',page:1,queue:'all',drafts:{},ov:null,updated:null,authorized:false,nav:false,hours:168,segment:'all',sessions:[],cursor:null,reviewed:{},specEdits:{},analyticsFilters:{}};
