  function select(name,label,options,value){return `<label class="aw-field"><span>${label}</span><select name="${name}">${options.map(([v,t])=>`<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(t)}</option>`).join('')}</select></label>`;}
