    if(action==='impersonate'){const c=st.detail,epoch=gateway.epoch;if(!(await confirm('Открыть кабинет клиента?','Служебный просмотр откроется в новой вкладке.',E(c.name)+' · №'+c.id)))return;const r=await mutate('/admin/clients/'+c.id+'/impersonate',{},{confirmed:true});if(epoch!==gateway.epoch||!r?.ok)return;const u=new URL(r.url,location.origin);if(!['https:','http:'].includes(u.protocol)||u.origin!==location.origin)throw Error('Сервер вернул неподдерживаемую ссылку.');modal('Кабинет клиента',link(u.href,'Открыть кабинет ↗','aw-btn primary'),{context:E(c.name)+' · №'+c.id});return;}
