  function qaForm(q){const draft=st.drafts['qa:'+q.id]||q;const choices=[['save','Сохранить без отправки']];if(!q.quiet&&q.publish_consent)choices.push(['publish','Опубликовать вопрос и ответ']);if(q.email)choices.push(['answer_quiet','Отправить личный ответ на почту']);actionForm('Ответ на вопрос №'+(q.num||q.id),`${q.question_raw&&q.question_raw!==q.question?note('<strong>Исходный вопрос</strong>'+E(q.question_raw)):''}${field('question','Формулировка вопроса',draft.question||q.question_raw,'textarea','required maxlength="600"')}${field('answer','Твой ответ',draft.answer||'','textarea','rows="7" maxlength="3000"')}${select('tag','Рубрика',Object.entries(st.data.qa?.tags||{}),draft.tag)}${select('action','Что сделать',choices,'save')}${!q.publish_consent?note('Согласие на публичный ответ не зафиксировано. Публикация недоступна.','warning'):''}`,{path:'/admin/qa/'+q.id,context:E(q.pseudonym||'Посетитель')+(q.quiet?' · личный вопрос':''),submit:'Выполнить',payload:d=>{if(d.action!=='save'&&d.answer.trim().length<5)throw Error('Для отправки нужен ответ от 5 символов.');return {action:d.action,question:d.question.trim(),answer:d.answer.trim(),tag:d.tag};},onSuccess:async()=>{delete st.drafts['qa:'+q.id];await load();refreshOverview();}});dialog.querySelector('form').addEventListener('input',()=>{st.drafts['qa:'+q.id]=Object.fromEntries(new FormData(dialog.querySelector('form')));});}
