  function operationName(path){if(path.includes('/bonus'))return 'Изменение бонусного счёта';if(path.includes('/broadcast'))return 'Отправка рассылки';if(path.includes('/gifts'))return 'Операция с сертификатом';if(path.includes('/orders'))return 'Операция по заказу';if(path.includes('/subs'))return 'Оплата подписки';return 'Изменение в мастерской';}
  async function pendingRead(key,button){const p=gateway.pending()[key];if(!p)return;let match=p.path.match(/^\/admin\/(orders|clients|gifts)\/(\d+)/),path=p.readPath|| (match?'/admin/'+match[1]+'/'+match[2]:p.path.includes('broadcast')?'/admin/broadcast/status':p.path.includes('/subs')?'/admin/subs':p.path==='/admin/orders'?'/admin/orders':p.path==='/admin/gifts'?'/admin/gifts':'/admin/overview');const epoch=gateway.epoch;button.disabled=true;const r=await gateway.get(path);if(epoch!==gateway.epoch)return;if(!r.ok)throw Error('Свежие данные недоступны. Блокировка остаётся.');const target=button.parentElement.querySelector('[data-pending-result]');const d=r.client||r.gift||r.order;let proof=d?kv([['Запись','№'+d.id],['Статус',STATUS[d.status]||GIFT[d.status]||'Данные обновлены'],['Баланс',d.bonus?.balance??d.balance??'Смотри платежи'],['Стоимость',M(d.price??d.amount)]])+(d.ledger||d.payments||d.events||[]).slice(0,30).map(x=>`<div class="aw-event"><time>${E(D(x.at,true))}</time><p>${E(x.label||events[x.kind]||x.kind||x.status||'Операция')} · ${E(x.delta??x.amount??x.data??'')} ${E(x.note||'')}</p></div>`).join(''):r.state?broadcastState(r.state):`<p class="aw-dialog-note">Свежий список. Отсутствие записи само по себе не доказывает отмену операции.</p>${(r.orders||r.gifts||r.pending||[]).slice(0,50).map(x=>`<div class="aw-event"><time>№${E(x.id)}<br>${E(D(x.created_at,true))}</time><p>${E(x.topic||x.label||x.code||'Запись')} · ${M(x.price??x.amount)}</p></div>`).join('')}${!r.orders&&!r.gifts&&!r.pending?kv([['Онлайн-оплата',r.pay_online===true?'Подключена':'Нет подтверждения'],['Реквизиты',r.requisites||'Нет данных'],['Квота',r.slots?.quota??'Нет данных']]):''}`;target.innerHTML=proof+btn('Я сверил результат','pending-reviewed',`data-key="${E(key)}"`,'small');st.reviewed[key]=gateway.epoch;button.disabled=false;}
  document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;try{if(action==='pending-read')await pendingRead(el.dataset.key,el);else if(action==='pending-reviewed'){const key=el.dataset.key;if(st.reviewed[key]!==gateway.epoch)return;const epoch=gateway.epoch;if(await confirm('Завершить сверку?','Я проверил фактический результат. Эта кнопка снимет блокировку, но не повторит и не отменит операцию.')){if(epoch!==gateway.epoch)return;gateway.reconcile(key);renderPending();toast('Сверка отмечена. Автоматического повтора не было.');}}else await handle(action,el);}catch(err){toast(err.message||'Действие не выполнено.');if(el.isConnected)el.disabled=false;}});
