  root.addEventListener('input',e=>{if(e.target.closest('#aw-message-form')&&st.selected)st.drafts['message:'+st.selected]=e.target.value;if(e.target.dataset.draft==='broadcast'){st.drafts.broadcast=e.target.value;const preview=document.getElementById('aw-broadcast-preview');if(preview)preview.textContent=e.target.value||'Твой текст появится здесь.';}if(e.target.name==='search'&&st.tab!=='orders'){st.q=e.target.value;/* Enter applies the filter without disrupting text selection. */}});
