  async function init(){await S.api.ready;const alk=location.hash.match(/(?:^#|&)alk=([A-Za-z0-9_-]+)/);if(alk){history.replaceState(null,'',location.pathname);const r=await S.api.post('/admin/login',{key:alk[1]});if(r.ok){if(r.token)S.api.setToken(r.token);if(r.session)S.api.setSessionHint(true);S.api.setUser(r.user||null);}else toast('Ссылка входа устарела. Запроси /panel в Telegram.');}await gate();}
